const cmds = [
  "sed -n '850,1140p' test/components/views/right_panel/UserInfo-test.tsx",
  "sed -n '540,1010p' src/components/views/right_panel/UserInfo.tsx",
  "find . -maxdepth 2 -type f \\( -name 'jest.config*' -o -name 'yarn.lock' \\) -print"
];
const results = await Promise.allSettled(cmds.map(cmd => tools.exec_command({cmd,workdir:"/app",yield_time_ms:10000,max_output_tokens:13000})));
results.forEach((r,i)=>text(`COMMAND ${i+1}\n${r.status==="fulfilled"?r.value.output:r.reason}`));

item.aggregated_output:
